\set ON_ERROR_STOP on
create temp table assert_count (n integer not null);
insert into assert_count values (0);
grant select,update on assert_count to service_role;
create function pg_temp.assert_true(v boolean, label text) returns void language plpgsql as $$ begin if v is distinct from true then raise exception 'ASSERT_FAIL %',label; end if; update assert_count set n=n+1; raise notice 'PASS %',label; end $$;
select pg_temp.assert_true((select count(*)=4 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('m2_create_scoped_receipt','m2_read_scoped_receipt','m2_claim_scoped_publish','m2_finish_scoped_publish')),'four_functions');
select pg_temp.assert_true((select relrowsecurity from pg_class where oid='public.m2_scoped_submission_receipts'::regclass),'rls_enabled');
select pg_temp.assert_true((select bool_and(not prosecdef and proconfig @> array['search_path=""']) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'm2_%_scoped_%'),'invoker_empty_path');
select pg_temp.assert_true(not has_table_privilege('anon','public.m2_scoped_submission_receipts','SELECT,INSERT,UPDATE,DELETE'),'anon_no_table');
select pg_temp.assert_true(not has_table_privilege('authenticated','public.m2_scoped_submission_receipts','SELECT,INSERT,UPDATE,DELETE'),'authenticated_no_table');
select pg_temp.assert_true(not has_function_privilege('anon','public.m2_create_scoped_receipt(text,text,text,text,jsonb,jsonb)','EXECUTE'),'anon_no_rpc');
select pg_temp.assert_true(not has_function_privilege('authenticated','public.m2_read_scoped_receipt(text,text,text)','EXECUTE'),'authenticated_no_rpc');
select pg_temp.assert_true(has_function_privilege('service_role','public.m2_create_scoped_receipt(text,text,text,text,jsonb,jsonb)','EXECUTE'),'service_rpc');
set role service_role;
select pg_temp.assert_true((select outcome='created' from public.m2_create_scoped_receipt(repeat('a',64),'fixture',repeat('1',32),repeat('b',64),'{"public_reference":"NOVORA-CB-20261030-AB12"}'::jsonb,'{"customer_name":"synthetic"}'::jsonb)),'create');
select pg_temp.assert_true((select count(*)=1 from public.concept_briefs),'brief_one');
select pg_temp.assert_true((select count(*)=1 from public.concept_brief_contacts),'contact_one');
select pg_temp.assert_true((select count(*)=1 from public.m2_scoped_submission_receipts),'receipt_one');
select pg_temp.assert_true((select outcome='existing' from public.m2_create_scoped_receipt(repeat('a',64),'fixture',repeat('1',32),repeat('b',64),'{"public_reference":"NOVORA-CB-20261030-CD34"}'::jsonb,'{}'::jsonb)),'duplicate_existing');
select pg_temp.assert_true((select outcome='conflict' from public.m2_create_scoped_receipt(repeat('a',64),'fixture',repeat('1',32),repeat('c',64),'{}'::jsonb,'{}'::jsonb)),'digest_conflict');
select pg_temp.assert_true((select count(*)=0 from public.m2_read_scoped_receipt(repeat('a',64),'other',repeat('1',32))),'other_identity_empty');
select pg_temp.assert_true((select count(*)=0 from public.m2_read_scoped_receipt(repeat('c',64),'fixture',repeat('1',32))),'other_scope_empty');
select pg_temp.assert_true((select stage='accepted' from public.m2_read_scoped_receipt(repeat('a',64),'fixture',repeat('1',32))),'read_accepted');
select pg_temp.assert_true(public.m2_claim_scoped_publish(repeat('a',64),'fixture',repeat('1',32)),'first_claim');
select pg_temp.assert_true(not public.m2_claim_scoped_publish(repeat('a',64),'fixture',repeat('1',32)),'second_claim_denied');
select pg_temp.assert_true(public.m2_finish_scoped_publish(repeat('a',64),'fixture',repeat('1',32),'UNKNOWN','UNKNOWN'),'finish_unknown');
select pg_temp.assert_true(not public.m2_finish_scoped_publish(repeat('a',64),'fixture',repeat('1',32),'published','enqueued'),'unknown_monotonic');
select pg_temp.assert_true(not public.m2_claim_scoped_publish(repeat('a',64),'fixture',repeat('1',32)),'unknown_no_claim');
select pg_temp.assert_true((select stage='UNKNOWN' and reason='UNKNOWN' from public.m2_read_scoped_receipt(repeat('a',64),'fixture',repeat('1',32))),'read_unknown');
reset role;
do $$ begin begin perform * from public.m2_create_scoped_receipt(repeat('a',64),'fixture',repeat('2',32),repeat('b',64),'{"public_reference":"NOVORA-CB-20261030-EF56"}'::jsonb,'{"customer_name":"REJECT"}'::jsonb); raise exception 'expected failure missing'; exception when check_violation then null; end; end $$;
select pg_temp.assert_true((select count(*)=1 from public.concept_briefs) and (select count(*)=1 from public.concept_brief_contacts) and (select count(*)=1 from public.m2_scoped_submission_receipts),'contact_failure_rollback');
do $$ begin begin perform * from public.m2_create_scoped_receipt(repeat('a',64),'fixture',repeat('3',32),repeat('b',64),'{"public_reference":"INVALID"}'::jsonb,'{}'::jsonb); raise exception 'expected failure missing'; exception when check_violation then null; end; end $$;
select pg_temp.assert_true((select count(*)=1 from public.concept_briefs) and (select count(*)=1 from public.concept_brief_contacts) and (select count(*)=1 from public.m2_scoped_submission_receipts),'receipt_failure_rollback');
select 'ASSERT_COUNT='||n from assert_count;
